create table if not exists public.timeline_daw_private_session_snapshots(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,name text not null,notes text not null default '',favorite boolean not null default false,revision integer not null default 1,state jsonb not null,checksum text not null,provenance jsonb not null,created_at timestamptz not null default now(),unique(owner_id,session_id,name,revision));
create table if not exists public.timeline_daw_private_snapshot_restores(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,snapshot_id text not null,safety_snapshot_id text not null,state text not null default 'applied' check(state in('applied','undone')),created_at timestamptz not null default now());
alter table public.timeline_daw_private_session_snapshots enable row level security;alter table public.timeline_daw_private_snapshot_restores enable row level security;
drop policy if exists timeline_daw_private_session_snapshots_owner on public.timeline_daw_private_session_snapshots;create policy timeline_daw_private_session_snapshots_owner on public.timeline_daw_private_session_snapshots using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
drop policy if exists timeline_daw_private_snapshot_restores_owner on public.timeline_daw_private_snapshot_restores;create policy timeline_daw_private_snapshot_restores_owner on public.timeline_daw_private_snapshot_restores using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
